(662, 'Se realiza instalación de nuevo socket para bombillo de cerámica. Se procede a retirar pedal de unidad N° 1 EMCO3111 y se instaló en la unidad de odontología N° 3. Se realiza reparación de pedal. Equipo queda operativo', '2022-02-18', '027a2abbba561720d08a00ac0a78b5bb.pdf', 'Se realiza instalación de pedal reparado', 0, 34, 1460),
(663, 'Se realiza revisión de la lámpara de la unidad de odontología N° 2. Se realiza cambio del socket porta bombillo de cerámica. Se evidencia desconexión en el sistema eléctrico se procede a ajustar. Se realizan pruebas eléctricas en la lámpara, la cual quedó funcionando. Se retira pedal neumático para posterior reparación y habilitación de la unidad de odontología N° 3. Equipo requiere pedal neumático. Equipo queda fuera de servicio', '2022-02-18', 'dafb1abddad45ad03d0054d3dec27579.pdf', 'Reparación de sistema eléctrico', 0, 34, 1492),
(664, 'Equipo operando correctamente', '2022-03-02', 'aa493e6b26f582f779469bbe078e525e.pdf', '', 0, 11, 1487),
(665, 'Es necesario cambiar el control cableado debido a que el conector se encuentra partido. ', '2022-02-15', '89073679f5f612048b6d0b5e956b43f6.pdf', 'Revisión del equipo', 0, 1, 813),
(666, 'Es necesario cambiar el control cableado debido a que el conector se encuentra partido. ', '2022-02-15', '6e99e89b165f2cc06640f8f6015bc34e.pdf', '', 0, 1, 1524),
(667, 'Se recibe equipo. \r\nEsta pendiente el respectivo informe de mantenimiento correctivo el cual relacionan que lo tiene Julian Quiñones. Por lo tanto se le solicita y se esta a la espera del mismo', '2022-03-11', '5dae80ff7d7876983d73800ae5ca5753.pdf', 'Acta de entrega empresa', 0, 7, 1150),
(668, 'Se realiza mantenimiento correctivo de consola de video en donde se realizó cambio de tarjeta DVI puesto\r\nque no reconocía los cabezales de cámara. Se realiza verificación general de la consola de video, se\r\nejecutaron las siguientes actividades:\r\nLimpieza general, interna y externa. Verificación de conexiones internas.\r\n• Verificación de funcionamiento del interruptor y fuente de Poder.\r\n• Verificación de conectores y test de colores.\r\n• Verificación de calidad de imagen y funcionamiento continúo.\r\nSe determina que en condiciones generales la consola de video funciona correctamente, se entrega\r\nverificado y en buen estado.\r\n', '2022-03-16', '4d05fce9b13a0a843e4892c7b1153d87.pdf', 'INFORME DE REPARACION', 0, 7, 1150),
(669, 'Previamente el equipo fue revisado.\r\n\r\nEl equipo se reporto por presiones bajas. Se reviso con analizador y se obtuvieron resultados dentro de lo resultado; sin evidenciarse la falla reportada.\r\nNormalmente el equipo lo reportan por esta falla cuando tiene las baterías malas. Ante lo cual se identifica que no retiene carga al desconectarse de la red eléctrica.\r\nSe realizo salida de almacén de una batería \"nueva\", sin embargo pese a probarse con la misma y con diferentes baterías que se verificaron cargadas el problema persiste.\r\nActualmente el equipo permanece fuera de servicio.', '2022-03-17', NULL, 'Estado del equipo', 2154, 7, 0),
(670, 'Se envía un correo electrónico a la empresa solicitando la revisión del equipo', '2022-03-16', '2887ef05b5d9a3a30e546a83d0e2f2c4.pdf', 'Solicitud de revision', 0, 7, 1537),
(671, 'Se reporta que el equipo no ilumina bien, por lo que se procede a revisarlo. Se identifica que el bombillo esta quemado, debido a esto, se revisa la etapa del transformador, donde se evidencia que el regulador TIC206D esta averiado, por lo que se encarga esta pieza para su posterior reparacion. El equipo se encuentra fuera de servicio, mientras se compra el repuesto', '2022-03-17', '767fcd1dc7ea8788dd6a63ef7b9bf3c7.jpeg', 'Repuesto averiado', 0, 116, 1540),
(672, 'Se revisan las conexiones y se encuentra que el componente LM2596 instalado en una reparacion anterior ya no funciona por lo que se encarga el repuesto para poder ajustarlo', '2022-03-18', '', 'Componente LM2596 averiado', 2155, 116, 0),
(673, 'SE REALIZA SALIDA DEL EQUIPO DE LA INSTITUCIÓN PARA CORRECTIVO QUE VA A SER REALIZADO POR INGENIERO NICOLAS ADRIAN PARRA OSPINA, SEGUN ORDEN DE COMPRA ON 89038\r\n', '2022-03-18', '6d315d5142be3923293ba22d6d14c812.pdf', 'SALIDA DEL EQUIPO PARA CORRECTIVO', 0, 8, 1389);
INSERT INTO `avances_correctivos` (`id`, `description`, `date`, `file`, `title`, `correctivo_general_id`, `usuario_id`, `orden_id`) VALUES
(674, 'Se procede a verificar voltajes de la UPS y del tablero, se encuentra falla en fase de AC caída de voltaje, lo produce que el equipo sea intermitente en su uso, se repara fallo en memoria RAM, equipo totalmente funcionable queda fuera de servicio por daño en la red eléctrica.', '2022-03-24', NULL, 'verificación de funcionamiento', 0, 30, 1561),
(675, 'El equipo se reporta por que no permite tomar el estudio de potenciales evocados, se contacta al proveedor y este da soporte en linea, sin embargo, por disponibilidad del equipo no se puede terminar de configurar el equipo y se agenda otra cita con el proveedor para 30/03/2022 ', '2022-03-23', NULL, 'Ajuste con proveedor', 0, 116, 1516),
(676, 'Se realizó la solicitud de cotización del bombillo ', '2022-02-28', NULL, 'Avance', 0, 34, 1484),
(677, 'El equipo se reporta debido a que no toma la presion no invasiva apropiadamente, se hacen las pruebas con el simulador y se encuentra que la falla no es de accesorios, sino por el contrario es del equipo. Debido a que el equipo tiene la garantia vigente, se contacta al proveedor para que lo revise.', '2022-03-25', NULL, 'Garantia vigente', 0, 116, 1556),
(678, 'La tarjeta electrónica tuvo una fractura por lo cual sus componentes presentaron daños. Se realiza reparación y revisión de la tarjeta electrónica y sus componentes, sin embargo, no funcionó adecuadamente. Se requiere cambio total del sistema electrónico.', '2022-03-30', NULL, 'AVANCE', 0, 34, 1574),
(679, 'Se realiza cambio y reparación de las mangueras internas del equipo. Se eliminan fugas. Pendiente la instalación de la válvula reguladora de presión para las piezas de mano.', '2022-03-30', NULL, 'Avance', 0, 34, 1573),
(680, 'Se realizo mantenimiento correctivo y preventivo, desarme parcial del equipo para cambio de los elementos referenciados en la orden de compra 89011. \r\nSe realiza ajuste de ensamble de tubo de inserción paciente, limpieza general, armado del equipo, pruebas de fugas, dando estas negativas y pruebas operativas reportan aprobadas', '2022-03-16', '94b56a5906faa6ad6172b7e525146b5c.pdf', 'Informe de reparación', 0, 7, 992),
(681, 'Se procede a cerrar la orden dado que actualmente el equipo se encuentra completamente operativo', '2022-04-04', NULL, 'Cierre de la orden', 201, 7, 0),
(682, 'Los equipos requieren UPS, para que en momentos que presente falla la energía estas no se apaguen', '2022-03-31', NULL, 'Revisión de central', 0, 11, 1522),
(683, 'Los equipos requieren UPS, para que en momentos que presente falla la energía estas no se apaguen', '2022-03-31', NULL, 'Revision central de monitoreo', 0, 11, 1522),
(684, 'Se observa que el agarre esta en mal estado y que el equipo esta pendiente por mantenimiento y ajuste de piezas. Pendiente aceite multiusos para llevar a cabo los ajustes', '2022-03-10', NULL, 'Diagnostico', 0, 116, 1518),
(685, 'Se lleva a cabo la revision del equipo y se evidencia que las piezas estan desajustadas y esta falto de lubricacion. A la espera de aceite multiusos para llevar a cabo el desmonte y ajuste de las piezas', '2022-03-10', NULL, 'Diagnostico', 0, 116, 1519),
(686, 'Se revisa el equipo y se evidencia que la cubierta de disco esta desprendida, ademas la rueda de inercia esta desajustada, lo que esta provocando la inestabilidad del usuario. Equipo temporalmente fuera de servicio, se esta a la espera de aceite multiusos para llevar a cabo el desmonte y ajuste de la eliptica', '2022-10-03', NULL, 'Diagnostico', 0, 116, 1520),
(687, 'Se revisa la eliptica y se evidencia que la rueda de inercia esta desajustada, lo que provoca la inestabilidad de la eliptica y que la carcaza se este abriendo.  Se esta a la espera de aceite multiusos para llevar a cabo el desmonte y ajuste de la eliptica.\r\n \r\n 			', '2022-03-10', NULL, 'Diagnostico', 0, 116, 1521),
(688, 'Equipo sin accesorios, no se encuentran accesorios para esa referencia en almacen. Accesorios pendientes por encargar', '2022-03-22', NULL, 'Accesorios faltantes', 0, 116, 1550),
(689, 'Equipo sin accesorios, no se encuentran accesorios para esa referencia en almacen. Accesorios pendientes por encargar', '2022-03-22', NULL, 'Accesorios faltantes', 0, 116, 1551),
(690, 'Equipo sin accesorios, no se encuentran accesorios para esa referencia en almacen. Accesorios pendientes por encargar', '2022-03-22', NULL, 'Equipo sin accesorios', 0, 116, 1552),
