(740, 'Se verifica error 20023. Con lo que no funciona ningún endoscopio. Se solicita a Jomedical enviar equipo en soporte ya que este debe salir de servicio', '2022-05-16', '3ec728a7c27b0e82cf2b76245ab58fd2.pdf', 'Revisión por error 20023', 0, 7, 1690),
(741, 'Se cambian los puertos de carga de la tablet y la carcasa, pero sigue sin encender la tablet, lo mas probable es que la bateria\r\nse encuentre totalmente dañada. Es necesario cambio de tablet. Se solicitan repuestos para cambio. ', '2022-04-05', '931940e136138acae911b2876dc0f3d1.pdf', '', 2213, 1, 0),
