(811, 'SE INSTALA REPUESTOS', '2022-12-01', '22bc7827ed0d9ff8234af543b73defe8.pdf', 'c-1190', 0, 7, 1428),
(812, 'SE REALIZÓ LO PROGRAMADO. EL VOLTAJE DE ALIMENTACIÓN ESTA EN EL VALOR ESPERADO.\r\nSIN EMBARGO SE RECOMIENDA LA REVISIÓN DE LA UPS CON EL FIN DE ASEGURAR QUE LA\r\nALIMENTACIÓN DEL EQUIPO ES OPTIMA.\r\nLOS MOVIMIENTOS DEL EQUIPO SE REALIZAN NORMALMENTE.\r\nCOMO SE SABIA CON ANTERIORIDAD, HAY PROBLEMAS DE CALIDAD DE IMAGEN EN EL DETECTOR 1.\r\nSE REALIZARON DIFERENTES PRUEBAS PARA DETERMINAR LA CAUSA DEL PROBLEMA.\r\nSE CONCLUYE QUE LA CAUSA DEL PROBLEMA ES EL ANORMAL FUNCIONAMIENTO DE LA FUENTE DE\r\nALTA TENSIÓN.\r\nSe intercambiaron las fuentes de Baja Tensión. El comportamiento de la fuente de Baja tensión en D1\r\nes el mismo.\r\nSe intercambiaron las fuentes de Alta Tensión.\r\nEl problema se cambió al D2.\r\nPor lo tanto, se puede concluir que la causa del problema del D1 es la fuente de Alta Tensión, pues al\r\ntener la fuente del D2, se ha normalizado su funcionamiento.\r\nEs necesario reemplazar la fuente. Una vez se reemplace es posible que surjan nuevos inconvenientes\r\nno detectados hasta el momento.\r\nLas fuentes se reubicaron en sus respectivos detectores.\r\nSe verificó que el Detector 2, esta operando correctamente.\r\nSe enviará cotización de la fuente.\r\nRECUERDESE QUE TODO EL TIEMPO, LA TEMPERATURA Y LA HUMEDAD RELATIVA DEBEN ESTAR\r\nCONTROLADAS.\r\nLA TEMPERATURA DEBE ESTAR ENTRE 18ºC y 26ºC. SE RECOMIENDA MANTENER LA TEMPERATURA\r\nEN UN RANGO ENTRE 20ºC y 23ºC.\r\nLA HUMEDAD RELATIVA DEBE ESTAR ENTRE 30% y 60%.\r\n', '2022-10-26', NULL, 'Revisión y diagnostico', 2249, 1, 0),
