(882, 'Se inspecciona el equipo con simulador paciente y este funciona correctamente. Se revisan los cables y no presenta ningún inconveniente. El equipo es funcional.\r\nFalso llamado.\r\nSe dan recomendaciones de uso del equipo.', '2023-04-18', NULL, '', 0, 121, 2711),
(883, 'Se inspecciona el equipo y se evidencia que el personal no había realizado el Cero de la línea arterial invasiva pese a que este arrojaba un mensaje de error de \"Cero requerido\". Se realiza el correcto cero y se explica al personal que a todas las líneas que pongan se les debe de hacer este procedimiento en el monitor. El equipo queda funcional en el servicio.', '2023-04-18', NULL, '', 0, 121, 2707),
(884, 'Se atiende llamado, se revisa equipo, equipo funciona correctamente, se revisa brazalete, se evidencia brazalete deteriorado, se realiza cambio de brazalete, se toman pruebas de funcionamiento, equipo funciona correctamente, se deja en el servicio en optimas condiciones.', '2023-04-20', NULL, '', 0, 42, 2720),
(885, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE EVIDENCIA DAÑO EN LA TOMA DE SEÑAL SPO2, SE REVISA INTERFAZ Y SENSOR SPO2, SE COMPRUEBA DAÑO EN LA INTERFAZ, SE REALIZA CAMBIO DE INTERFAZ, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.', '2023-04-21', NULL, '', 0, 42, 2730),
(886, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, EQUIPO FUNCIONA CORRECTAMENTE, SE REVISA BRAZALETE, SE EVIDENCIA FUGA, SE REALIZA CAMBIO DE VEJIGA, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEVUELVE AL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-04-24', NULL, '', 0, 42, 2739),
(887, 'Se realiza la solicitud del equipo bajo condición de garantía.', '2023-04-24', 'd15f1b814397e35f86fbe32ce3114eb2.pdf', '', 0, 16, 2723),
(888, 'Se anexa orden de salida del equipo por parte de equipadora medica s.a para revisión por garantía. ', '2023-04-25', 'ee3db0280c4a6f857c86be3869ad4c42.pdf', '', 0, 16, 2723),
(889, 'SE INSPECCIONA EL EQUIPO Y SE EVIDENCIA QUE SE QUEDÓ CONGELADA LA IMAGEN, SE REALIZA REINICIO DEL SISTEMA Y ESTE RESPONDE CORRECTAMENTE. SE REALIZAN PRUEBAS DE FUNCIONAMIENTO LAS CUALES SON SUPERADAS SATISFACTORIAMENTE. EL EQUIPO QUEDA FUNCIONAL EN EL SERVICIO.\r\nNO SE EVIDENCIA CONGELAMIENTO DEL SISTEMA NUEVAMENTE.', '2023-05-02', NULL, '', 0, 42, 2744),
(890, 'Se realiza el día 02 de mayo informe de la falla al proveedor AGFA, y solicitan espacio para revisar el equipo a las 3:00 pm ', '2023-05-03', '0aa7afa0f683ca97b0f76cf3e0b2e677.pdf', 'Diagnostico', 2273, 1, 0),
(891, 'SE INSPECCIONA EL EQUIPO Y SE EVIDENCIA SUCIEDAD EN LOS CONECTORES A LOS CLAMPS Y CHUPAS POR EXCESO DE GEL, LO QUE AISLABA LA SEÑAL. SE REALIZA LIMPIEZA INTEGRAL Y VUELVE A PRESENTAR CONDUCTIVIDAD ADECUADA. SE REALIZA CAMBIO DE CABLE DE PODER Y QUEDÒ FUNCIONANDO EN EL SERVICIO.', '2023-04-24', NULL, '', 0, 42, 2735),
(892, 'SE INSPECCIONA ACCESORIO Y SE EVIDENCIA DAÑO EN EL BOTÒN. SE REALIZA CAMBIO DE MANGO CON BOTÒN Y SE RECTIFICA FUNCIONAMIENTO, PERMITIENDO MARCACIÒN DE EVENTOS NUEVAMENTE. EL ACCESORIO QUEDA FUNCIONAL EN EL SERVICIO.', '2023-04-25', NULL, '', 0, 42, 2736),
(893, 'SE INSPECCIONA ACCESORIO Y SE EVIDENCIA DAÑO EN EL BOTÒN. SE REALIZA CAMBIO DE MANGO CON BOTÒN Y SE RECTIFICA FUNCIONAMIENTO, PERMITIENDO MARCACIÒN DE EVENTOS NUEVAMENTE. EL ACCESORIO QUEDA FUNCIONAL EN EL SERVICIO.', '2023-04-25', NULL, '', 0, 42, 2737),
