(904, 'Se reporta a AGFA, quienes indican que el ingeniero Edward estará en sitio  a las 2 pm', '2023-05-19', '73f364094a7cc25fe86d132fcb778a1c.pdf', 'Reporte a servicio tecnico', 2277, 1, 0),
