(1003, 'se atiende llamado por correctivo, se evidencia modulo de EKG apagado en pantalla, se procede a realizar activación de modulo de EKG. se entrega equipo en buenas condiciones operativas.', '2023-09-28', NULL, 'monitor de signos vitales', 0, 42, 3359),
(1004, 'Se atiende llamado por correctivo, se evidencia saturador en mal estado, se realiza cambio del mismo. Se entrega equipo en buenas condiciones operativas al servicio.', '2023-09-28', NULL, 'monitor de signos vitales', 0, 42, 3360),
(1005, 'Se atiende llamado por correctivo, se evidencia interfaz en malas condiciones, se realiza cambio de interfaz y se entrega equipo en buenas condiciones operativas al servicio.', '2023-09-28', NULL, 'monitor de signos vitales', 0, 42, 3361),
(1006, 'Se atiende llamado por correctivo, se realiza inspección visual y funcional del equipo durante 2 días donde se evidencia buen funcionamiento del mismo. Se realizan pruebas de funcionamiento en todos los modos de operación. Se entrega equipo en buenas condiciones físicas y operativas.', '2023-09-29', NULL, 'Diagnostico calentador', 0, 42, 3348),
(1007, 'Se atiende llamado por correctivo, se realiza inspección visual y funcional de su sistemas eléctrico/electrónico, se evidencia buen estado de componentes, por precaución se realiza cambio de filtro hidrofóbico, se realizan pruebas de funcionamiento en todos los modos de operación y el equipo responde correctamente. Se recomienda utilizar el equipo en buenas condiciones físicas para su optimo funcionamiento ya que puede afectar el flujo de aire de la incubadora. Se entrega equipo en buenas condiciones operativas.    ', '2023-09-29', NULL, 'incubadora', 0, 42, 3347),
(1008, 'Se atiende llamado por correctivo, se evidencia sensor de temperatura externa en malas condiciones, se realiza ajuste del mismo, se entrega equipo en buenas condiciones físicas y operativas al servicio.', '2023-10-03', NULL, 'TH', 0, 42, 3365),
(1009, 'Se atiende llamado por correctivo, se evidencia modulos de inactivos en pantalla, se realiza activación de los mismos. Se entrega equipo en buenas condiciones físicas y operativas al servicio.', '2023-10-03', NULL, 'Monitor de signos vitales', 0, 42, 3366),
(1010, 'SE ATIENDE LLAMADO, SE REVISA ACCESORIO, SE EVIDENCIA DAÑO EN LA INTERFAZ DE SATURACION,  SE REALIZA CAMBIO DE INTERFAZ, SE TOMAN PRUEBAS DE FUNCIONAMIENTO. EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES, ', '2023-10-03', NULL, '', 0, 42, 3371),
(1011, 'se atiende llamado por correctivo, se evidencia en mal estado saturador de spo2, se realiza reparación del mismo. Se entrega equipo en buenas condiciones fisicas y operativas en el servicio.', '2023-10-04', NULL, 'monitor de signos vitales', 0, 42, 3373),
(1012, 'SE ATIENDE LLAMADO POR CORRECTIVO, SE EVIDENCIA SENSOR DE SPO2 EN MAL ESTADO, SE REALIZA CAMBIO DEL MISMO, SE ENTREGA EQUIPO EN BUENAS CONDICIONES FISICAS Y OPERATIVAS.', '2023-10-05', NULL, 'MONITOR DE SIGNOS VITALES', 0, 42, 3379),
(1013, 'se atiende llamado por correctivo, se evidencia saturador en mal funcionamiento, se realiza cambio del mismo. Se entrega equipo en buenas condiciones fisicas y operativas al servicio.', '2023-10-11', NULL, 'monitor de signos vitales', 0, 42, 3394),
(1014, 'se atiende llamado por correctivo, se evidencia daño en motor, se realizan lubricación de electrovalvulas, cambio de motor. se realizan pruebas de funcionamiento con equipo patron y el equipo funciona correctamente. se entrega equipo en buenas condiciones fisicas y operativas.', '2023-10-12', NULL, 'monitor de signos vitales', 0, 42, 3380),
(1015, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE EVIDENCIA BATERÍA DESCARGADA, SE DEJA CARGANDO BATERÍA EQUIPO FUNCIONA CORRECTAMENTE, SE  REALIZA RECOMENDACIÓN DEL USO DEL EQUIPO, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONEN. ', '2023-10-13', NULL, '', 0, 42, 3397),
(1016, 'SE REALIZA INSTALACIÓN DEL SENSOR SPO2 Y BRAZALETE, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-10-13', NULL, '', 0, 42, 3404),
(1017, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE EVIDENCIA CABLE ECG, EN MALAS CONDICIONES, SE REALIZA CAMBIO DE CABLE ECG, POR UNO NUEVO, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES,', '2023-10-18', NULL, '', 0, 42, 3421),
(1018, 'Se reporta la falla del equipo al proveedor encargado, se realiza el día 17 de octubre de 2023 empaque del equipo de la institución el cual sera llevado a la ciudad de Bogotá para ser revisado, diagnosticado y reparado. El mismo día se entrega un equipo de backup a la institución para no afectar el funcionamiento del servicio. ', '2023-10-18', 'd8af83de257bdb7a1347947a3b9d5407.pdf', 'Se reporta al proveedor encargado', 0, 121, 3416),
(1019, 'Se solicita repuesto de acuerdo a reporte de diagnostico realizado el 10 de agosto de 2023 por parte de la empresa SIEMENES HEALTHINEERS S.A.S.', '2023-08-31', 'fce7c0788a95333ae499f61bdaed5579.pdf', 'Se realiza solicitud de repuesto pendiente ', 0, 121, 2824),
(1020, 'Se adjunta orden de compra realizada el día 28 de Septiembre de 2023, se encuentra pendiente que llegue repuesto y se realice la instalación del mismo. ', '2023-09-28', 'cf067eb788b85259705898e0ef67573e.pdf', 'orden de compra on-89618', 0, 121, 2824),
(1021, 'se atiende llamado por correctivo, se realiza inspecciòn visual y funcional, se evidencia equipo en buenas condiciones operativas. se concluye que el equipo estaba en modo neonatal para la mediciòn de nibp por lo que no era posible la toma cuando se utilizaba en persona adulta.', '2023-10-23', NULL, 'monitor de signos vitales', 0, 42, 3454),
(1022, 'se atiende llamado, se realizan pruebas de funcionamiento y se evidencia regulador en buen estado y 1 flujometro. Los equipos si se pueden utilizar sin ningun problemas.', '2023-10-23', NULL, 'Flujometros y regulador', 0, 42, 3447),
(1023, 'Se atiende llamado por correctivo, se realiza inspecciòn visual y funcional y se evidencia equipo en buen funcionamiento. Se entrega equipo funcionalmente ok', '2023-10-24', NULL, 'monitor de signos vitales', 0, 42, 3459),
(1024, 'Se realiza entrega de IPC en el servicio de sala de operaciones. ', '2023-08-18', NULL, 'entrega del equipo', 2280, 258, 0),
(1025, 'SE ATIENDE LLAMADO, SE EVIDENCIA BATERIA EN MAL ESTADO. ANTERIORMENTE, SE LE HIZO CAMBIO DE BATERIA POR UNA DE OTRO EQUIPO FUERA DE SERVICIO. SE RECOMIENDA UTILIZAR EL EQUIPO CONECTADO YA QUE NO SE CUENTAN CON BATERIAS NUEVAS PARA SU CAMBIO.', '2023-10-24', NULL, 'monitor de signos vitales', 0, 42, 3460),
(1026, 'Se atiende llamado, se instala accesorios adultos. equipo queda funcional.', '2023-10-24', NULL, '', 0, 42, 3461),
(1027, 'Se atiende llamado, se instala accesorios adultos. equipo queda funcional.', '2023-10-24', NULL, '', 0, 42, 3462),
(1028, 'Se atiende llamado, se instala accesorios adultos. equipo queda funcional.', '2023-10-24', NULL, '', 0, 42, 3463),
(1029, 'SE ATIENDE LLAMADO POR CORRECTIVO, SE EVIDENCIA PERILLA EN MAL ESTADO, SE REALIZA CAMBIO DE PERILLA YA QUE PRESENTABA FRACTURA. SE ENTREGA EQUIPO EN BUENAS CONDICIONES OPERATIVAS.', '2023-10-25', NULL, 'monitor de signos vitales', 0, 42, 3466),
(1030, 'El día de hoy 25 de octubre de 2023, se realiza recogida del equipo por parte del personal de Biotronitech para ser enviado al laboratorio en la ciudad de Bogotá para ser diagnosticado y revisado. ', '2023-10-25', '3ef40c31988eb6e76d44c087f80b8ef0.pdf', 'Recogida del equipo', 0, 121, 3427),
(1031, 'Se le instala sensor spo2 pediatrico, se toman pruebas de funcionamiento (ECG, NIBP, SPO2), EQUIPO FUNCIONA CORRECTAMENTE, SE DEVUELVE AL SERVICIO EN OPTIMAS CONDICIONES ', '2023-11-02', NULL, '', 0, 258, 2562),
(1032, 'Se le instala sensor spo2 pediatrico, se toman pruebas de funcionamiento (ECG, NIBP, SPO2), EQUIPO FUNCIONA CORRECTAMENTE, SE DEVUELVE AL SERVICIO EN OPTIMAS CONDICIONES ', '2023-11-02', NULL, '', 0, 258, 2746),
(1033, 'SE ATIENDE LLAMDO, SE REVISA EQUIPO, SE REALIZA CAMBIO DE MANGUERA DEBIDO A QUE LA MANGUERA ACTUAL PRESENTA DAÑOS, SE TOMAN PRUEBAS DE FUNCIONAMEINTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEVUELVE AL SERVICIO EN OPTIMAS CODNICIONES. ', '2023-11-02', NULL, '', 0, 42, 3529),
(1034, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE EVIDENCIA BOMBILLO FUNDIDO, SE REALIZA INSTALACION Y CAMBIO DE BOMBILLO, EQUIPO QUEDA FUNCIONAL.', '2023-11-02', NULL, '', 0, 42, 3528),
(1035, 'Se atiende llamado, se realiza equipo, se realizan la prueba de auto test, equipo pasa correctamente, se realiza reviso con equipo patrón (impulso 7000DP) el funcionamiento de las palas y cable ECG, equipo opera correctamente, se devuelve al servicio en optimas condiciones. ', '2023-11-03', NULL, '', 0, 42, 3486),
(1036, 'El día de hoy 3/11/2023 se realiza entrega al servicio de equipo backup cabezal de cámara SN: RT873240-H, para que el servicio no se vea afectado mientras llega el equipo en Comodato que se encuentra en reparación. ', '2023-11-03', 'f1f1b52d9f5b440bfeb328ad2f8d370b.pdf', 'SE ENTREGA EQUIPO BACKUP ', 0, 121, 3427),
(1037, 'Se realiza resolución GG-2032-2023 para la visita, diagnostico y mantenimiento correctivo del equipo. Se encuentra pendiente el equipo para ser recogido', '2023-11-02', '3bdf45b825d1d4bb9bb6a23797d4ea51.pdf', 'sE REALIZA RESOLUCIÓN PARA ATENDER EQUIPO', 0, 42, 36),
(1038, 'La empresa realiza la entrega del equipo a la institución. El equipo es retornado al servicio. ', '2023-05-09', 'e8a585a71fc304bcb59ebfb82b9743a1.pdf', 'INGRESO DEL EQUIPO', 0, 258, 2723),
(1039, 'se atiende llamado, se evidencia monitor sin batería, se recomienda utilizar el equipo conectado a la corriente ya que en el momento no se cuentan con baterías. Se esta a la espera de orden de compra. ', '2023-11-24', NULL, 'monitor de signos vitales', 0, 42, 3587),
(1040, 'Se atiende llamado, se realiza inspección visual y funcional por 24 horas de funcionamiento continuo y el equipo no presentó fallas, se recomienda al momento de utilizar el equipo no interrumpir el flujo de aire ya que eso permite que el sensor detecte una temperatura mayor a la establecida por lo que el equipo por seguridad se bloquea. ', '2023-11-24', NULL, 'calentador paciente', 0, 42, 3561),
(1041, 'Se atiende llamado, se evidencia cuello fracturado, por lo que se realiza reconstrucción del mismo. Se recomienda utilizar el equipo de manera fija ya que por el golpe y para poder realizar la reconstrucción del equipo fue necesario dejarlo en una sola posición. Se entrega equipo en buenas condiciones operativas. ', '2023-11-24', NULL, 'video laringoscopio', 0, 42, 3559),
(1042, 'se atiende llamado por correctivo, se evidencia saturador en mal estado, se realiza ajuste de pines, brazalete en buen estado. se realiza cambio de manguera. Se entrega equipo en buenas condiciones fisicas y operativas.', '2023-11-24', NULL, 'monitor de signos vitales', 0, 42, 3591),
(1043, 'Se atiende llamado por correctivo, se realiza inspección visual y funcional donde se evidencia buen funcionamiento de los transductores y del equipo. se recomienda utilizar el equipo con buena gel y bien ajustados al paciente. Se entrega equipo en buenas condiciones físicas y operativas.', '2023-11-24', NULL, 'monitor fetal ', 0, 42, 3589),
(1044, 'SE ATIENDE LLAMADO, SE  INFORMA CON LA JEFE DEL SERVICIO QUE LA PACIENTE ARRANCO EL ACCESORIO, OCASIONADO DAÑOS EN LA TOMA DE SIGNOS, SE REALIZA CAMBIO DE CABLE ECG, SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE. SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-12-05', NULL, '', 0, 42, 3604),
(1045, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO, SE REALIZA PRUEBA DE ALISTAMIENTO DIARIO. EQUIPO PASA TODAS LAS PRUEBAS. EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-12-07', NULL, '', 0, 42, 3610),
(1046, 'SE ATIENDE LLAMADO, SE REVISA EQUIPO, EQUIPO FUNCIONA CORRECTAMENTE, SE REVISA BRAZALETE, SE EVIDENCIA BRAZALETE CON OBSTRUCCION, SE REALIZA  LIBERACION, SE TOMAN PRUEBAS DE FUNCIONAMEINTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-12-12', NULL, '', 0, 42, 3620),
(1047, 'SE ATIENDE LLAMADO, SE REVISA ACCESORIO, SE  EVIDENCIA SENSOR SPO2 DAÑADO, SE REALIZA CAMBIO DEL SENSOR. SE TOMAN PRUEBAS DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES. ', '2023-12-12', NULL, '', 0, 42, 3621),
(1048, 'Acciones correctivas: Se verificó el log de errores y se encontraron multiples fallas\r\n(Problemas de la fuente del detector bloqueada, problemas del IPPC, problemas,\r\nproblemas con el GEO Module, problemas de colisión, problemas con los\r\nelectrofrenos de la mesa del movimiento longitudinal, problemas con la estación 3D),\r\nse procedió a realizar limpieza de la SIB (sistem interface board) y de la fuente de\r\nalimentación del detector, se reinició el equipo y el voltaje en el detector está presente,\r\nse hizo recarga de software, se recreó la base de datos y se calibró el detector,\r\ngenerador y tubo de Rayos X ok, se hizo calibración de toda la geometría (Stand y\r\nmesa) ok, se realiza pruebas con phamton y el equipo trabajó sin novedad,\r\nNota: en el log de errores se evidenció muy constante el error enmv_at_startup_high,\r\nes debido a La señal de solicitud de Habilitar movimiento (ENMV) está activa durante\r\nel inicio del sistema y presenta el mensaje de solo posible movimiento parcial de la\r\ngeomtría, se debe reemplazar el modulo GEO, se solicitará en esta orden de trabajo.\r\npara poder habilitar los movimientos se debe mover el botón del stand, se entrega\r\nequipo operativo con restricciones. se debe programar 2 dias más de servicio para\r\ncontinuar con los correctivo y ejecutar el preventivo.', '2023-12-15', 'f1b80cc432ab125fd27b01e83353008c.pdf', '', 2307, 1, 0),
(1049, 'se realiza instalación de sensor nuevo, se toman pruebas de funcionamiento. equipo funciona correctamente, se deja en el servicio en optimas condiciones. ', '2023-12-15', NULL, '', 0, 42, 3633),
(1050, 'Se configura alarma de la nevera WONDER de la central de mezclas en los invertalos 2°C y 8°C.', '2023-06-26', 'e0e031e46358986d44739237095dc2ee.pdf', 'Configuración de alarma ', 2308, 255, 0),
(1051, 'SE ATIENDE LLAMADO, SE EVIDENCIA BATERIAS DESGASTADAS, SE LE INFORME AL SERVICIO QUE DEBE DE SOLICITAR PILAS A ALMACEN PARA LA INSTALACCION   Y CORRECTO FUNCIONAMIENTO DEL EQUIPO', '2023-12-19', NULL, '', 0, 7, 3646),
(1052, 'SE ATIENDE LLAMADO, SE REVISA SATURADOR, SE EVIDENCIA DAÑO EN EL SENSOR  SPO2, SE REALIZA CAMBIO DEL SENSOR   SE TOMAN PRUEBAS  DE FUNCIONAMIENTO, EQUIPO FUNCIONA CORRECTAMENTE, SE DEJA EN EL SERVICIO EN OPTIMAS CONDICIONES.', '2023-12-26', NULL, '', 0, 7, 3660),
(1053, 'Se verifica la solicitud y se confirma que requieren 2 cilindros de aire medicinal', '2024-01-04', NULL, 'Confirmacion de solicitud', 0, 121, 3682),
(1054, 'SE ATIENDE LLAMADO POR CORRECTIVO, SE REALIZA INSPECCIÓN VISUAL Y FUNCIONAL CON EQUIPO PATRON DE FLUJO Y EL EQUIPO RESPONDE BIEN. SE EVIDENCIA QUE LA VALVULA PEEP QUE UTILIZAN EN EL SERVICIO ESTA PRESENTANDO FALLAS POR LO QUE PRESENTA DICHO ERROR. SE RECOMIENDA REALIZAR CAMBIO DE DICHA VALVULA. ', '2024-01-04', NULL, 'VENTILADOR MECANICO', 0, 16, 3679),
(1055, 'SE ATIENDE LLAMADO POR CORRECTIVO, SE EVIDENCIA MODULO DE IMPRESORA MAL POSICIONADO, SE RECOMIENDA UTILIZAR EL EQUIPO CON CUIDADO PARA SU OPTIMO FUNCIONAMIENTO. SE ENTREGA EQUIPO EN BUENAS CONDICIONES OPERATIVAS Y FÍSICAS AL SERVICIO.', '2023-12-29', NULL, 'MONITOR FETAL', 0, 16, 3662),
(1056, 'SE ATIENDE LLAMADO, SE REALIZA INSPECCIÓN VISUAL Y FUNCIONAL Y SE EVIDENCIA QUE EL VENTILADOR ESTA CONECTADO A LA MANGUERA DEL COMPRESOR. CABE RESALTAR, QUE LOS VENTILADORES DE ESTE MODELO NO UTILIZAN COMPRESOR POR EL MOMENTO Y DEBEN SER UTILIZADOS DESDE LA CONEXIÓN EN LA PARED. SE REALIZAN PRUEBAS DE FUNCIONAMNIENTO CON EQUIPO PATRON. SE ENTREGA EQUIPO FUNCIONAL EN EL SERVICIO.', '2024-01-09', NULL, 'ventilador mecanico', 0, 42, 3686),
(1057, 'se atiende llamado, se revisa equipo, se evidencia daño en el bombillo, se realiza cambio de bombillo, se ajusta puerto de conexión, equipo queda funcional, se deja en el servicio en optimas condiciones. ', '2024-01-15', NULL, '', 0, 121, 3713),
(1058, 'Fisicamente la sonda cuenta con avería en la membrana cercana a la mitad de la misma y una pequeña perforación cercana a la punta de la sonda.\r\nAl conectarse al equipo la reconoce pero después de un tiempo arroja mensaje de error y no puede ser usada.\r\nSe realizan tests diagnósticos de transductor se evidencia una gran cantidad de .elementos dañados\r\n\r\nSe requiere cambio de sonda X7-2t (transesofagica)', '2023-12-19', 'a2e374f67f60b050ccd83d2c3d88f3e9.pdf', 'revisión en sitio del equipo', 0, 1, 3586),
(1059, 'Dado que el daño es de un accesorio, el equipo como tal (ecografo) se encuentra funcional.  A la fecha se recibe por medio del proveedor NEUROCARE una sonda transesofagica que queda en custodia y responsabilidad del proveedor para dar atención a los estudios pendientes y a las cirugias de cardio en donde es usada esta sonda.', '2024-01-16', NULL, '', 0, 1, 3586),
(1060, 'Se  atiende llamado, se revisa equipo se evidencia que el equipo no cuenta con brazalete, se realiza instalación de un brazalete adulto, pediátrico y neonatal n° 5, para su correcto funcionamiento, equipo queda funcional y en el servicio', '2024-01-17', NULL, '', 0, 42, 3722),
(1061, 'Se atiende llamado, se revisa equipo se evidencia que el equipo no cuenta con brazalete, se realiza instalación de un brazalete adulto, pediátrico y neonatal n° 5, para su correcto funcionamiento, equipo queda funcional y en el servicio\r\n', '2024-01-17', NULL, '', 0, 42, 3723),
(1062, 'Se atiende llamado, se revisa equipo se evidencia que el equipo no cuenta con brazalete, se realiza instalación de un brazalete adulto, pediátrico y neonatal n° 5, para su correcto funcionamiento, equipo queda funcional y en el servicio\r\n', '2024-01-17', NULL, '', 0, 42, 3724),
(1063, 'Se atiende llamado, se revisa equipo se evidencia que el equipo no cuenta con brazalete, se realiza instalación de un brazalete adulto, pediátrico y neonatal n° 5, para su correcto funcionamiento, equipo queda funcional y en el servicio\r\n', '2024-01-17', NULL, '', 0, 42, 3725),
(1064, 'Se atiende llamado, se revisa mesa de cirugía, se realiza limpieza interna de tarjetas electrónicas,  se evidencia falta de soporte estático en el lado izquierdo   y soporte estático flojo en el lado derecho  se realiza reparación e instalación de un nuevo soporte, se realizan pruebas de funcionamiento, equipo funciona correctamente, se deja en el servicio en optimas condiciones.  ', '2024-01-11', NULL, '', 0, 42, 3701);
INSERT INTO `avances_correctivos` (`id`, `description`, `date`, `file`, `title`, `correctivo_general_id`, `usuario_id`, `orden_id`) VALUES
(1065, 'SE REALIZA REVISION GENERAL DEL EQUIPO. SE REALIZA ACTUALIZACION DE SOFTWARE A SP5 SEGUN INDICACIONES DE \r\nFABRICA CON LO CUAL SE CORRIGE EL ERROR PRINCIPAL REPORTADO. EN EL MOMENTO DE HACER PRUEBAS FINALES DE \r\nFUNCIONAMIENTO SE DETECTA QUE NO ENCIENDE EL INDICADOR DE AC. SE REVISA ESTADO Y SALIDA DE FUENTE DE VOLTAJE Y \r\nSE ENCUENTRA QUE ESTA EN MAL ESTADO. EL EQUIPO DESPUES DE REVISION SE EVIDENCIA QUE EL CARGADOR NO FUNCIONA, QUEDA FUERA DE SERVICIO', '2023-11-16', 'a7883ffd6afb5714c47953d0a11dde56.pdf', '', 0, 11, 3562),
(1066, 'Se realiza instalación de la AWS PC y board control, y se evidencia que el equipo no realiza encendido total. el proveedor indica que es necesario cambiar 2 contactores y una resistencia (los cuales deben cotizar). Para poder continuar con el proceso de reparación del equipo.', '2024-01-24', 'cc6652a28179e5e66d575acd3a56bafb.pdf', 'Instalacion de partes ', 0, 1, 1561),
(1067, 'Se evidencia daño en el portabombillo, se realiza cambio de portabombillo, equipo queda funcional ', '2024-01-29', NULL, '', 0, 42, 3808),
(1068, 'Se atiende llamado, se revisa equipo, se evidencia bombillo quemado, se realiza cambio de bombillo, se observa mala posición de baterías, se acomodan correctamente, equipo queda funcional ', '2024-01-29', NULL, '', 0, 42, 3807),
(1069, 'Se atiende llamado, se revisa equipo, equipo funciona correctamente, el error es el acople de la pared ya se debe de realizar orden a mantenimiento industrial.', '2024-01-29', NULL, '', 0, 42, 3803),
(1070, 'Se atiende llamado, se revisa equipo, se evidencia brazalete, con fuga se realiza cambio de brazalete, se toman pruebas de funcionamiento equipo opera correctamente, se deja en el servicio en optimas condiciones. ', '2024-01-30', NULL, '', 0, 42, 3811),
(1071, 'Se realiza revisión del ventilador  mecánico.\r\n Se hace  prueba de calibración del sensor de flujo y este arroja mensaje\"sensor de flujo defectuoso\" se hizo la prueba con 4 sensores de flujo nuevos se revisa cable de sensor de flujo y persiste el mensaje', '2024-02-01', NULL, 'Revision', 0, 11, 3819),
(1072, 'Se atiende llamado, se revisa equipo, se evidencia cable suelto, se acomoda correctamente, se realiza pruebas de funcionamiento, equipo opera correctamente, se deja en el servicio en optimas condiciones. ', '2024-02-05', NULL, '', 0, 42, 3825),
(1073, 'Se atiende llamado, se evidencia bombillo en mal estado, se realiza cambio del mismo y se entrega equipo funcional en el servicio.', '2024-02-06', NULL, 'lampara cielitica ', 0, 30, 3833),
