(1279, 'ANTERIORMENTE SE HABIA REALIZADO UN REEMPLAZO PROVISIONAL DEL CABLE DE EXTENSION DEL EQUIPO BIS, ESTE NUEVO CABLE ESTUVO EN USO HASTA EL DIA LUNES 23 DE JUNIO EN EL QUIROFANO 8, PERO EL DIA MARTES EN LA MAÑANA, AL MOMENTO DE INICIAR CIRUGIA, YANO SE ENCONTRABA. DURANTE TODA LA SEMANA SE HA BUSCADO EN TODOSLOS QUIROFANOS, PERO HASTA EL MOMENTO NO HA SIDO POSIBLE LOCALIZARLO. ', '2025-06-27', NULL, 'PERDIDA DEL CABLE PROVISIONAL ', 0, 18, 13675);
INSERT INTO `avances_correctivos` (`id`, `description`, `date`, `file`, `title`, `correctivo_general_id`, `usuario_id`, `orden_id`) VALUES
(1280, 'Se realiza visita de inspección y diferentes pruebas de funcionamiento por parte del proveedor Electromedica en donde se evidencia la falla reportada, y se evidencia que la membrana de la válvula exhalatoria del ventilador no se encuentra. Razón por la cual el ventilador no mantiene el flujo de oxigeno constante ni los volúmenes programados. El equipo queda fuera de servicio y en espera de compra de membrana o valvula exhalatoria completa. ', '2025-06-25', '2ff74de5c73a1dc2d737d224ed88fc06.pdf', 'Revisión por parte del proveedor', 2483, 1, 0),
(1281, 'Se realiza instalación de impresora, se calibra y se toman pruebas de funcionamiento con los tocos intrauterino y transductor de fetocardia adicional a eso se realiza instalación de marcador de eventos nuevos. Equipo queda funcional y se realiza instalación al servicio ', '2025-07-04', NULL, '', 0, 42, 2621),
(1282, 'Se espera orden de compra para nuevos accesorios ', '2025-06-30', NULL, '', 0, 258, 13316),
